// Shows the dark-theme twin of each documentation figure while the slate scheme is active.
// Every assets/name.svg has an assets/name-dark.svg generated by scripts/make_dark_figures.py.
// Pages keep referencing the light file; this swaps the src on page load (including
// mkdocs-material instant navigation) and whenever the reader toggles the palette.
(() => {
  // The noodl-physics-* logos carry their own #only-light / #only-dark variants.
  const FIGURE = /assets\/(?!noodl-physics)[^/]+?(-dark)?\.svg$/;

  const apply = () => {
    const dark = document.body.getAttribute("data-md-color-scheme") === "slate";
    for (const img of document.querySelectorAll(".md-content img")) {
      const src = img.getAttribute("src");
      const match = src && src.match(FIGURE);
      if (!match) continue;
      if (dark && !match[1]) img.setAttribute("src", src.replace(/\.svg$/, "-dark.svg"));
      if (!dark && match[1]) img.setAttribute("src", src.replace(/-dark\.svg$/, ".svg"));
    }
  };

  document$.subscribe(apply);
  new MutationObserver(apply).observe(document.body, {
    attributes: true,
    attributeFilter: ["data-md-color-scheme"],
  });
})();
